#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pbkdf2_matches_rfc6070_style_vector() {
        // RFC 7914 §11 PBKDF2-HMAC-SHA-256 vector: P="passwd", S="salt", c=1.
        let mut out = [0u8; 64];
        pbkdf2_sha256(b"passwd", b"salt", 1, &mut out).expect("derive");
        assert_eq!(hex_encode(&out[..16]), "55ac046e56e3089fec1691c22544b605");
    }

    #[test]
    fn pbkdf2_refuses_zero_iterations() {
        let mut out = [0u8; 32];
        assert!(pbkdf2_sha256(b"p", b"s", 0, &mut out).is_err());
    }

    #[test]
    fn password_round_trips_and_rejects_tampering() {
        // A low count keeps the test fast; production uses the default.
        let encoded = password_hash_with(b"correct horse", 1_000).expect("hash");
        assert!(password_verify(b"correct horse", &encoded));
        assert!(!password_verify(b"correct horse ", &encoded));
        assert!(!password_verify(b"", &encoded));

        // Two hashes of the same password differ: the salt is fresh.
        let again = password_hash_with(b"correct horse", 1_000).expect("hash");
        assert_ne!(encoded, again);
        assert!(password_verify(b"correct horse", &again));

        // Malformed records answer false, never panic and never error out.
        assert!(!password_verify(b"x", ""));
        assert!(!password_verify(b"x", "bcrypt$10$deadbeef$cafe"));
        assert!(!password_verify(b"x", "pbkdf2-sha256$0$aa$bb"));
        assert!(!password_verify(b"x", "pbkdf2-sha256$1000$zz$bb"));
        assert!(!password_verify(b"x", "pbkdf2-sha256$1000$aa"));
    }

    /// The record format is the fork SDK's: a record hashed there verifies
    /// here, so a store carried across the Core change keeps its accounts.
    #[test]
    fn a_fork_era_record_still_verifies() {
        let mut derived = [0u8; SHA256_DIGEST_LEN];
        pbkdf2_sha256(b"correct horse", b"0123456789abcdef", 1_000, &mut derived).expect("derive");
        let record = format!(
            "pbkdf2-sha256$1000${}${}",
            hex_encode(b"0123456789abcdef"),
            hex_encode(&derived)
        );
        assert!(password_verify(b"correct horse", &record));
    }
}
